import datetime

from ta_moler.events.egen.genericegen_lineevent import GenericEgenLineEvent


class EgenFailure(GenericEgenLineEvent):
    """EgenFailure event class."""

    _re_no_such_file_or_directory = r'count_pcap_packets\(\):fopen: No such file or directory'
    _re_cant_open_file = r'ERROR: count_pcap_packets\(\) cant open file'
    _re_is_another_primary_process_running = r'Is another primary process running\?'

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """
        Event for egen command failure.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        """
        super(EgenFailure, self).__init__(
            connection=connection,
            runner=runner,
            till_occurs_times=till_occurs_times,
            detect_patterns=[
                EgenFailure._re_no_such_file_or_directory,
                EgenFailure._re_cant_open_file,
                EgenFailure._re_is_another_primary_process_running
            ],
            match='any'
        )


